def breakPalindrome(palindrome: str) -> str:
    n = len(palindrome)
    if n == 1:
        return ""
    palindrome = list(palindrome)
    # Only check first half (excluding middle if odd)
    for i in range(n // 2):
        if palindrome[i] != 'a':
            palindrome[i] = 'a'
            return ''.join(palindrome)
    # All 'a' in first half
    palindrome[-1] = 'b'
    return ''.join(palindrome)
